// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/agents", wrapper.ListAgents)
	m.HandleFunc("POST "+options.BaseURL+"/agents", wrapper.RegisterAgent)
	m.HandleFunc("POST "+options.BaseURL+"/agents/{id}:release", wrapper.ReleaseAgent)
	m.HandleFunc("POST "+options.BaseURL+"/agents/{id}:reserve", wrapper.ReserveAgent)
	m.HandleFunc("GET "+options.BaseURL+"/capabilities", wrapper.GetCapabilities)
	m.HandleFunc("POST "+options.BaseURL+"/configs", wrapper.CreateConfig)
	m.HandleFunc("GET "+options.BaseURL+"/configs/{id}", wrapper.GetConfig)
	m.HandleFunc("POST "+options.BaseURL+"/configs/{id}:validate", wrapper.ValidateConfig)
	m.HandleFunc("GET "+options.BaseURL+"/modules", wrapper.ListModules)
	m.HandleFunc("POST "+options.BaseURL+"/modules", wrapper.InstallModule)
	m.HandleFunc("DELETE "+options.BaseURL+"/modules/{name}/{version}", wrapper.DeleteModule)
	m.HandleFunc("GET "+options.BaseURL+"/modules/{name}/{version}", wrapper.GetModule)
	m.HandleFunc("GET "+options.BaseURL+"/runs", wrapper.ListRuns)
	m.HandleFunc("POST "+options.BaseURL+"/runs", wrapper.StartRun)
	m.HandleFunc("GET "+options.BaseURL+"/runs/{id}", wrapper.GetRun)
	m.HandleFunc("GET "+options.BaseURL+"/runs/{id}/captures", wrapper.ListCaptures)
	m.HandleFunc("POST "+options.BaseURL+"/runs/{id}/captures", wrapper.StartCapture)
	m.HandleFunc("GET "+options.BaseURL+"/runs/{id}/captures/{capture_id}", wrapper.DownloadCapture)
	m.HandleFunc("GET "+options.BaseURL+"/runs/{id}/metrics", wrapper.GetRunMetrics)
	m.HandleFunc("GET "+options.BaseURL+"/runs/{id}/metrics:stream", wrapper.StreamRunMetrics)
	m.HandleFunc("GET "+options.BaseURL+"/runs/{id}/report", wrapper.GetRunReport)
	m.HandleFunc("POST "+options.BaseURL+"/runs/{id}:stop", wrapper.StopRun)

	return m
}
